// ─── File: MemoryDemo.java ───
// Multiple top-level classes for a runnable demo; each would be its own file.
package com.bank.mem;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class MemoryDemo {
    private static final Logger log = Logger.getLogger("BankLog");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return "[" + r.getLevel() + "] " + r.getMessage() + System.lineSeparator();
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // 'rajesh' and 'priya' are REFERENCES on the stack; the Account
        // OBJECTS they point to live on the shared HEAP.
        Account rajesh = new Account("SAV2001", "Rajesh", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya",  new BigDecimal("250000"));

        TransferService service = new TransferService();
        service.transfer(rajesh, priya, new BigDecimal("50000"));
        service.transfer(priya, rajesh, new BigDecimal("10000"));

        // Static counter lives in the Method Area (Metaspace), shared by all.
        log.info(() -> "Bank: " + TransferService.BANK_NAME
                + " | total transfers (static, Method Area): " + TransferService.getTotalTransfers());
        log.info(() -> "Rajesh (heap object) balance: Rs." + rajesh.getBalance());
        log.info(() -> "Priya  (heap object) balance: Rs." + priya.getBalance());
    }
}

// ─── Would be in Account.java (instances live on the HEAP) ───
class Account {
    private final String accountId;   // field → stored inside the heap object
    private final String holderName;
    private BigDecimal balance;

    Account(String id, String name, BigDecimal bal) {
            this.accountId = id;
            this.holderName = name
            this.balance = bal;
    }
    void debit(BigDecimal a)  { balance = balance.subtract(a); }
    void credit(BigDecimal a) { balance = balance.add(a); }
    String getHolderName() { return holderName; }
    BigDecimal getBalance() { return balance; }
}

// ─── Would be in TransferService.java ───
class TransferService {
    private static final Logger log = Logger.getLogger("BankLog");

    // STATIC state → Method Area / Metaspace, one copy for the whole class.
    static final String BANK_NAME = "National Bank of India";
    private static int totalTransfers = 0;

    void transfer(Account from, Account to, BigDecimal amount) {
        // 'from', 'to', 'amount' are LOCALS → this thread's STACK frame.
        BigDecimal before = from.getBalance();     // local → stack
        if (before.compareTo(amount) < 0) {
            log.warning(() -> "Skip: insufficient funds for " + from.getHolderName());
            return;
        }
        from.debit(amount);   // mutates the HEAP object
        to.credit(amount);    // mutates the HEAP object
        totalTransfers++;     // mutates STATIC state in Method Area
        log.info(() -> "Transferred Rs." + amount + " " + from.getHolderName()
                + " → " + to.getHolderName());
        // When transfer() returns, the stack frame (before/amount) is popped.
    }

    static int getTotalTransfers() { return totalTransfers; }
}
